const seed = Date.now() + Math.random() * 1000;
const randomIndex = Math.floor(seed % items.length);
const selectedItem = items[randomIndex];

return [{ json: selectedItem.json }];

const items = $input.all();
const scoredItems = [];

for (const item of items) {
  const feedItem = item.json;
  let score = 0;

  // Skip if no title or link
  if (!feedItem.title || !feedItem.link) continue;

  // Score based on how recent (simple version)
  const pubDate = new Date(feedItem.pubDate || feedItem.date);
  const now = new Date();
  const hoursOld = (now - pubDate) / (1000 * 60 * 60);

  if (hoursOld <= 24) score += 5;
  else if (hoursOld <= 48) score += 3;
  else score += 1;

  // Score based on title keywords (customize these)
  const title = (feedItem.title || '').toLowerCase();
  const keywords = ['ai', 'tech', 'innovation', 'startup', 'emerging tech', 'jobs of the future'];

  keywords.forEach(keyword => {
    if (title.includes(keyword)) score += 2;
  });

  scoredItems.push({
    title: feedItem.title,
    link: feedItem.link,
    description: feedItem.description,
    pubDate: feedItem.pubDate,
    score: score
  });
}

// Get top 3
const topItems = scoredItems
  .sort((a, b) => b.score - a.score)
  .slice(0, 15)
  .map(item => ({ json: item }));

return topItems;

// Extract title and date using regex patterns
const content = $input.first().json.message.content;
let extracted = {
  title: null,
  publishDate: null
};

// Common title patterns
const titlePatterns = [
  /<title[^>]*>(.*?)<\/title>/i,
  /<h1[^>]*>(.*?)<\/h1>/i,
  /Title:\s*([^\n\r]+)/i,
  /"headline":\s*"([^"]+)"/i
];

// Common date patterns  
const datePatterns = [
  /Published Time:\s*([^\n\r]+)/i,
  /"datePublished":\s*"([^"]+)"/i,
  /"publishedTime":\s*"([^"]+)"/i,
  /Publication Date:\s*([^\n\r]+)/i,
  /\b(\d{4}-\d{2}-\d{2})\b/,
  /\b([A-Za-z]+ \d{1,2},? \d{4})\b/
];

// Extract title
for (const pattern of titlePatterns) {
  const match = content.match(pattern);
  if (match && match[1]?.trim()) {
    extracted.title = match[1].trim().replace(/<[^>]*>/g, '');
    break;
  }
}

// Extract date
for (const pattern of datePatterns) {
  const match = content.match(pattern);
  if (match && match[1]?.trim()) {
    const dateStr = match[1].trim();
    // Convert to YYYY-MM-DD format
    const date = new Date(dateStr);
    if (!isNaN(date.getTime())) {
      extracted.publishDate = date.toISOString().split('T')[0];
      break;
    }
  }
}

return [{ json: extracted }];

const items = $input.all();

for (const item of items) {
  const html = item.json.html || item.json.data;
  let imageUrl = '';

  if (html) {
    // Try multiple methods to find the best image

    // Method 1: Open Graph image (most reliable for articles)
    let match = html.match(/<meta[^>]*property=["']og:image["'][^>]*content=["']([^"']+)["'][^>]*>/i);
    if (match) {
      imageUrl = match[1];
    }

    // Method 2: Twitter card image
    if (!imageUrl) {
      match = html.match(/<meta[^>]*name=["']twitter:image["'][^>]*content=["']([^"']+)["'][^>]*>/i);
      if (match) {
        imageUrl = match[1];
      }
    }

    // Method 3: Featured/hero images (common in blog posts)
    if (!imageUrl) {
      const featuredSelectors = [
        /<img[^>]*class=["'][^"']*featured[^"']*["'][^>]*src=["']([^"']+)["'][^>]*>/i,
        /<img[^>]*class=["'][^"']*hero[^"']*["'][^>]*src=["']([^"']+)["'][^>]*>/i,
        /<img[^>]*class=["'][^"']*post-image[^"']*["'][^>]*src=["']([^"']+)["'][^>]*>/i,
        /<img[^>]*class=["'][^"']*wp-post-image[^"']*["'][^>]*src=["']([^"']+)["'][^>]*>/i
      ];

      for (const regex of featuredSelectors) {
        match = html.match(regex);
        if (match) {
          imageUrl = match[1];
          break;
        }
      }
    }

    // Method 4: First image in article content
    if (!imageUrl) {
      match = html.match(/<(?:article|div[^>]*class=["'][^"']*(?:content|post|article)[^"']*["'])[^>]*>.*?<img[^>]*src=["']([^"']+)["'][^>]*>/is);
      if (match) {
        imageUrl = match[1];
      }
    }

    // Method 5: Any reasonably sized image (width > 300px)
    if (!imageUrl) {
      const imgMatches = html.match(/<img[^>]*src=["']([^"']+)["'][^>]*>/gi);
      if (imgMatches) {
        for (const imgTag of imgMatches) {
          const srcMatch = imgTag.match(/src=["']([^"']+)["']/);
          const widthMatch = imgTag.match(/width=["']?(\d+)/);

          if (srcMatch && (!widthMatch || parseInt(widthMatch[1]) > 300)) {
            imageUrl = srcMatch[1];
            break;
          }
        }
      }
    }

    // Clean up relative URLs
    if (imageUrl && imageUrl.startsWith('//')) {
      imageUrl = 'https:' + imageUrl;
    } else if (imageUrl && imageUrl.startsWith('/')) {
      const linkUrl = item.json.link || '';
      const baseUrl = linkUrl.match(/^https?:\/\/[^\/]+/);
      if (baseUrl) {
        imageUrl = baseUrl[0] + imageUrl;
      }
    }

    // Validate it's actually an image
    if (imageUrl && !imageUrl.match(/\.(jpg|jpeg|png|gif|webp|svg)(\?.*)?$/i)) {
      // Check if it might be a valid image URL without extension
      if (!imageUrl.includes('image') && !imageUrl.includes('photo') && !imageUrl.includes('pic')) {
        imageUrl = '';
      }
    }
  }

  // Add image data to your item
  item.json.imageUrl = imageUrl;
  item.json.hasImage = !!imageUrl;

  // Log for debugging
  if (imageUrl) {
    console.log(`Found image: ${imageUrl}`);
  } else {
    console.log('No image found for article');
  }
}

