const input = $input.first().json;

// Check if this is ChatGPT response format
let content;
if (input.choices && input.choices[0]?.message?.content) {
  // This is ChatGPT API response
  content = input.choices[0].message.content;
} else if (input.message?.content) {
  // Alternative ChatGPT format
  content = input.message.content;
} else if (typeof input === 'string') {
  // Direct string content
  content = input;
} else {
  // Fallback - try to get any string content
  content = JSON.stringify(input);
}

let extracted = {
  title: null,
  publishDate: null,
  source: 'regex_extraction'
};

// If ChatGPT already returned JSON, try to parse it first
try {
  // Remove markdown code blocks if present
  let cleanContent = content.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

  // Try to parse as JSON first
  const parsed = JSON.parse(cleanContent);
  if (parsed.title) {
    extracted.title = parsed.title;
  }
  if (parsed.publishDate) {
    extracted.publishDate = parsed.publishDate;
  }

  // If we got what we need from JSON, return it
  if (extracted.title && extracted.publishDate) {
    return [{ json: extracted }];
  }
} catch (e) {
  // Not JSON, continue with regex extraction
}

// Enhanced title patterns for plain text content
const titlePatterns = [
  // JSON format patterns
  /"title":\s*"([^"]+)"/i,
  /"headline":\s*"([^"]+)"/i,

  // HTML patterns
  /<title[^>]*>(.*?)<\/title>/i,
  /<h1[^>]*>(.*?)<\/h1>/i,

  // Plain text patterns
  /^Title:\s*([^\n\r]+)/im,
  /^#\s*([^\n\r]+)/im, // Markdown H1
  /\nTitle:\s*([^\n\r]+)/i,

  // MIT News specific patterns
  /^([^\n]+)\n={3,}/m, // Title followed by === underline
  /What does the future hold for ([^\?]+)\?/i,

  // First significant line (fallback)
  /^([A-Z][^\n]{10,100})/m
];

// Enhanced date patterns
const datePatterns = [
  // JSON format patterns
  /"publishDate":\s*"([^"]+)"/i,
  /"datePublished":\s*"([^"]+)"/i,
  /"publishedTime":\s*"([^"]+)"/i,

  // Plain text patterns
  /Published Time:\s*([^\n\r]+)/i,
  /Publication Date:\s*([^\n\r]+)/i,
  /September \d{1,2}, \d{4}/i,

  // Standard date formats
  /\b(\d{4}-\d{2}-\d{2})\b/,
  /\b([A-Z][a-z]+ \d{1,2},? \d{4})\b/,
  /\b(\d{1,2}[\/\-]\d{1,2}[\/\-]\d{4})\b/,

  // Relative patterns
  /\b(Mon|Tue|Wed|Thu|Fri|Sat|Sun),?\s*([A-Z][a-z]+ \d{1,2},? \d{4})/i
];

// Extract title
for (const pattern of titlePatterns) {
  const match = content.match(pattern);
  if (match && match[1]?.trim()) {
    let title = match[1].trim()
      .replace(/<[^>]*>/g, '') // Remove HTML tags
      .replace(/\s+/g, ' ')    // Normalize whitespace
      .replace(/["""]/g, '"')  // Normalize quotes
      .trim();

    if (title.length > 5) { // Minimum title length
      extracted.title = title;
      break;
    }
  }
}

// Extract date
for (const pattern of datePatterns) {
  const match = content.match(pattern);
  if (match && match[1]?.trim()) {
    const dateStr = match[1].trim();

    try {
      // Try to parse the date
      const date = new Date(dateStr);
      if (!isNaN(date.getTime()) && date.getFullYear() > 1990) {
        extracted.publishDate = date.toISOString().split('T')[0];
        break;
      }
    } catch (e) {
      // Continue to next pattern
    }
  }
}

